// Parse AI response and decide: duplicate or not?
const raw = $input.first().json.message?.content || $input.first().json.text || '';
const article = $('Prepare Dedup Payload').first().json;
const config = $('⚙️ Configuration').first().json;

let result;
try {
  let jsonStr = raw;
  const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fenceMatch) jsonStr = fenceMatch[1].trim();
  result = JSON.parse(jsonStr);
} catch (e) {
  // If parsing fails, assume not duplicate (safe default)
  result = { isDuplicate: false, confidence: 0, reason: 'فشل تحليل رد الذكاء الاصطناعي' };
}

return [{
  json: {
    articleId: article.id,
    title: article.title,
    source_name: article.source_name,
    url: article.url,
    isDuplicate: result.isDuplicate === true,
    matchedTitle: result.matchedTitle || null,
    confidence: result.confidence || 0,
    reason: result.reason || '',
    aggregatorUrl: config.aggregatorUrl
  }
}];

// Article passed dedup check — output it for the rewrite+publish workflow
const article = $input.first().json;
return [{
  json: {
    articleId: article.articleId,
    title: article.title,
    source_name: article.source_name,
    url: article.url,
    status: 'dedup_passed',
    message: `✅ ${article.title} — مقال فريد، جاهز للنشر`
  }
}];
